// Modelo simplificado (no es el código de expo-updates): qué actualización elige un teléfono.
const servidor = [
  { id: "u1", runtimeVersion: "1.0.0", creada: "2026-11-02", nota: "arreglo de una cita" },
  { id: "u2", runtimeVersion: "1.0.0", creada: "2026-11-09", nota: "texto de una pantalla" },
  { id: "u3", runtimeVersion: "1.1.0", creada: "2026-11-12", nota: "usa la cámara (librería nativa nueva)" },
];

function elegir(runtimeVersion) {
  const compatibles = servidor.filter((u) => u.runtimeVersion === runtimeVersion);
  compatibles.sort((a, b) => b.creada.localeCompare(a.creada));
  return compatibles[0] ?? null;
}

function simular(nombre, binario) {
  let corriendo = "incluida en el binario";
  console.log(`\n${nombre} (runtimeVersion ${binario})`);
  for (let apertura = 1; apertura <= 2; apertura++) {
    console.log(`  apertura ${apertura}: corre ${corriendo}`);
    const oferta = elegir(binario);
    if (oferta && oferta.id !== corriendo) {
      console.log(`    consulta al servidor: ofrece ${oferta.id} (${oferta.nota}); la baja`);
      corriendo = oferta.id; // por defecto se aplica en el próximo arranque
    } else {
      console.log("    consulta al servidor: nada compatible más nuevo");
    }
  }
}

simular("Teléfono con la versión 1.0.0 de la tienda", "1.0.0");
simular("Teléfono con la versión 1.1.0 de la tienda", "1.1.0");
simular("Teléfono que nunca actualizó (0.9.0)", "0.9.0");
